import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { Row, Col, Badge, Button, Table, InputGroup, Form, Nav, Tab, ProgressBar, Card } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faStar, faStarHalfAlt, faShoppingCart, faBolt } from '@fortawesome/free-solid-svg-icons';
import axios from 'axios';

const MangaDetail = () => {
  const { id } = useParams();
  const [manga, setManga] = useState(null);
  const [quantity, setQuantity] = useState(1);
  const [activeTab, setActiveTab] = useState('description');

  useEffect(() => {
    const fetchManga = async () => {
      try {
        const response = await axios.get(`/api/manga/${id}`);
        setManga(response.data);
      } catch (error) {
        console.error('Error fetching manga:', error);
      }
    };

    fetchManga();
  }, [id]);

  const handleQuantityChange = (value) => {
    const newValue = parseInt(value);
    if (newValue >= 1 && newValue <= 99) {
      setQuantity(newValue);
    }
  };

  const renderRatingStars = (rating) => {
    const stars = [];
    const fullStars = Math.floor(rating);
    const hasHalfStar = rating % 1 !== 0;

    for (let i = 0; i < fullStars; i++) {
      stars.push(<FontAwesomeIcon key={i} icon={faStar} className="text-warning" />);
    }

    if (hasHalfStar) {
      stars.push(<FontAwesomeIcon key="half" icon={faStarHalfAlt} className="text-warning" />);
    }

    return stars;
  };

  if (!manga) {
    return <div>Loading...</div>;
  }

  return (
    <>
      {/* Breadcrumb */}
      <nav aria-label="breadcrumb" className="mb-4">
        <ol className="breadcrumb">
          <li className="breadcrumb-item"><Link to="/">Trang chủ</Link></li>
          <li className="breadcrumb-item">
            <Link to={`/category/${manga.category.id}`}>{manga.category.name}</Link>
          </li>
          <li className="breadcrumb-item active" aria-current="page">{manga.title}</li>
        </ol>
      </nav>

      <Row>
        {/* Manga Image */}
        <Col md={4} className="mb-4">
          <div className="position-relative">
            <img src={manga.coverImage} className="img-fluid rounded shadow" alt={manga.title} />
            {manga.isNewRelease && (
              <Badge bg="danger" className="position-absolute top-0 end-0 m-2">Mới</Badge>
            )}
          </div>
        </Col>

        {/* Manga Info */}
        <Col md={8}>
          <h1 className="mb-3">{manga.title}</h1>
          
          <div className="d-flex align-items-center mb-3">
            <div className="rating me-3">
              {renderRatingStars(manga.rating)}
              <span className="ms-1">{manga.rating}</span>
            </div>
            <span className="text-muted">|</span>
            <span className="ms-3">{manga.reviewCount} đánh giá</span>
            <span className="text-muted">|</span>
            <span className="ms-3">{manga.soldCount} đã bán</span>
          </div>

          <div className="price-section mb-4">
            <h2 className="price">
              {manga.price.toLocaleString('vi-VN')} đ
            </h2>
            {manga.originalPrice && (
              <>
                <span className="text-muted text-decoration-line-through">
                  {manga.originalPrice.toLocaleString('vi-VN')} đ
                </span>
                {manga.discountPercentage && (
                  <Badge bg="danger" className="ms-2">-{manga.discountPercentage}%</Badge>
                )}
              </>
            )}
          </div>

          <div className="mb-4">
            <h5>Thông tin chi tiết:</h5>
            <Table>
              <tbody>
                <tr>
                  <td className="fw-bold">Tác giả:</td>
                  <td>
                    <Link to={`/author/${manga.author.id}`}>{manga.author.name}</Link>
                  </td>
                </tr>
                <tr>
                  <td className="fw-bold">Nhà xuất bản:</td>
                  <td>{manga.publisher}</td>
                </tr>
                <tr>
                  <td className="fw-bold">Số trang:</td>
                  <td>{manga.pageCount}</td>
                </tr>
                <tr>
                  <td className="fw-bold">Khổ sách:</td>
                  <td>{manga.dimensions}</td>
                </tr>
                <tr>
                  <td className="fw-bold">Ngày phát hành:</td>
                  <td>{new Date(manga.releaseDate).toLocaleDateString('vi-VN')}</td>
                </tr>
              </tbody>
            </Table>
          </div>

          <div className="purchase-section mb-4">
            <Row className="align-items-center">
              <Col xs="auto">
                <Form.Label>Số lượng:</Form.Label>
                <InputGroup style={{ width: '150px' }}>
                  <Button
                    variant="outline-secondary"
                    onClick={() => handleQuantityChange(quantity - 1)}
                  >
                    -
                  </Button>
                  <Form.Control
                    type="number"
                    value={quantity}
                    onChange={(e) => handleQuantityChange(e.target.value)}
                    className="text-center"
                    min="1"
                    max="99"
                  />
                  <Button
                    variant="outline-secondary"
                    onClick={() => handleQuantityChange(quantity + 1)}
                  >
                    +
                  </Button>
                </InputGroup>
              </Col>
              <Col xs="auto" className="ms-3">
                <span className="text-muted">{manga.stockCount} sản phẩm có sẵn</span>
              </Col>
            </Row>
          </div>

          <div className="d-flex gap-2">
            <Button variant="primary" size="lg">
              <FontAwesomeIcon icon={faShoppingCart} className="me-2" />
              Thêm vào giỏ
            </Button>
            <Button variant="danger" size="lg">
              <FontAwesomeIcon icon={faBolt} className="me-2" />
              Mua ngay
            </Button>
          </div>
        </Col>
      </Row>

      {/* Description and Reviews */}
      <Row className="mt-5">
        <Col xs={12}>
          <Tab.Container activeKey={activeTab} onSelect={setActiveTab}>
            <Nav variant="tabs" className="mb-3">
              <Nav.Item>
                <Nav.Link eventKey="description">Mô tả</Nav.Link>
              </Nav.Item>
              <Nav.Item>
                <Nav.Link eventKey="reviews">Đánh giá</Nav.Link>
              </Nav.Item>
            </Nav>

            <Tab.Content>
              <Tab.Pane eventKey="description">
                <div className="bg-light p-4 rounded" dangerouslySetInnerHTML={{ __html: manga.description }} />
              </Tab.Pane>

              <Tab.Pane eventKey="reviews">
                <Row>
                  <Col md={4}>
                    <div className="text-center mb-4">
                      <h4>Đánh giá trung bình</h4>
                      <div className="display-4 fw-bold text-warning">{manga.rating}</div>
                      <div className="rating mb-2">
                        {renderRatingStars(manga.rating)}
                      </div>
                      <div className="text-muted">{manga.reviewCount} đánh giá</div>
                    </div>

                    <div className="rating-bars">
                      {[5, 4, 3, 2, 1].map(star => (
                        <div key={star} className="d-flex align-items-center mb-2">
                          <div className="text-warning me-2">
                            {star} <FontAwesomeIcon icon={faStar} />
                          </div>
                          <ProgressBar
                            className="flex-grow-1"
                            style={{ height: '8px' }}
                            variant="warning"
                            now={70}
                          />
                          <div className="ms-2">70%</div>
                        </div>
                      ))}
                    </div>
                  </Col>

                  <Col md={8}>
                    {manga.reviews.map(review => (
                      <Card key={review.id} className="mb-3">
                        <Card.Body>
                          <div className="d-flex justify-content-between mb-2">
                            <div className="d-flex align-items-center">
                              <img
                                src={review.user.avatar}
                                className="rounded-circle me-2"
                                width="40"
                                height="40"
                                alt={review.user.name}
                              />
                              <div>
                                <h6 className="mb-0">{review.user.name}</h6>
                                <div className="rating">
                                  <FontAwesomeIcon icon={faStar} className="text-warning" />
                                  <span className="ms-1">{review.rating}</span>
                                </div>
                              </div>
                            </div>
                            <small className="text-muted">
                              {new Date(review.createdAt).toLocaleDateString('vi-VN')}
                            </small>
                          </div>
                          <p className="card-text">{review.content}</p>
                        </Card.Body>
                      </Card>
                    ))}
                  </Col>
                </Row>
              </Tab.Pane>
            </Tab.Content>
          </Tab.Container>
        </Col>
      </Row>

      {/* Related Manga */}
      <section className="mt-5">
        <h3 className="mb-4">Truyện liên quan</h3>
        <Row xs={2} md={4} lg={6} className="g-4">
          {manga.relatedManga.map(related => (
            <Col key={related.id}>
              <Card className="manga-card h-100">
                <Card.Img variant="top" src={related.coverImage} alt={related.title} />
                <Card.Body>
                  <Card.Title as="h6">{related.title}</Card.Title>
                  <p className="price mb-0">{related.price.toLocaleString('vi-VN')} đ</p>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      </section>
    </>
  );
};

export default MangaDetail;
